package org.telegram.ui.Components;

import android.app.Activity;
import android.content.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.zip.*;
import org.json.*;
import org.telegram.messenger.*;
import org.telegram.ui.ActionBar.*;
import org.telegram.ui.DevGramAppearanceAccess;
import org.telegram.ui.Cells.TextSettingsCell;

/** Download source assets independently of applying a workshop design. */
public final class DevGramWorkshopSourcesSheet {
    private static final int SINGLE=7698,PACKAGE=7699,MAX_ASSET=5*1024*1024,MAX_PACKAGE=48*1024*1024;
    private final BaseFragment host;private final JSONObject work,document;private final Theme.ResourcesProvider resources;private final long viewer;
    private final ArrayList<Source> sources=new ArrayList<>();private Source selected;private volatile boolean closed,busy;private TextView status;
    private static final class Source{final String label,url,filename,sha,mime;final boolean download;Source(String label,String url,String filename,String sha,String mime,boolean download){this.label=label;this.url=url;this.filename=filename;this.sha=sha;this.mime=mime;this.download=download;}}
    public DevGramWorkshopSourcesSheet(BaseFragment host,JSONObject work,Theme.ResourcesProvider resources){this.host=host;this.work=DevGramProfileDocument.copy(work);this.resources=resources;viewer=host.getUserConfig().getClientUserId();document=DevGramProfileDocument.publicValue(work.optJSONObject("document"));collect();}
    private String t(String value){return DevGramLocale.text(value);}private boolean valid(){return !closed&&DevGramProfileCustomization.enabled()&&host.getUserConfig().getClientUserId()==viewer;}
    private void collect(){
        HashSet<String> seen=new HashSet<>();JSONArray textures=DevGramProfileTextures.sources(document);for(int i=0;i<textures.length();i++){String source=textures.optString(i),filename=source.substring(6);if(seen.add(source))sources.add(new Source(t("Изображение")+" "+(i+1),DevGramProfileTextures.imageUrl(source),filename,filename.substring(0,64),"image/"+(filename.endsWith(".jpg")?"jpeg":filename.substring(65)),true));}
        for(String key:new String[]{"nameFontFile","chatFontFile"}){JSONObject font=document.optJSONObject(key);String sha=font==null?"":font.optString("sha256");if(sha.matches("[a-f0-9]{64}")&&seen.add(sha))sources.add(new Source(t(key.equals("nameFontFile")?"Шрифт имени":"Шрифт сообщений"),DevGramProfilePolicy.BASE+"studio/fonts/"+sha+".ttf",sha+".ttf",sha,"font/ttf",true));}
        JSONArray rows=document.optJSONArray("blocks");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null||DevGramProfileRowSpec.type(row)!=10)continue;String url=row.optString("url");if(url.startsWith("https://")&&seen.add(url))sources.add(new Source(row.optString("title").isEmpty()?t("Изображение"):row.optString("title"),url,"","","",false));}
        JSONObject media=document.optJSONObject("media");if(media!=null)for(String slot:new String[]{"banner","page"}){JSONObject asset=media.optJSONObject(slot);long message=asset==null?0:asset.optLong("message");if(message>0&&message<=Integer.MAX_VALUE)sources.add(new Source(t(slot.equals("banner")?"Шапка и баннер":"Фон профиля"),"https://t.me/"+DevGramPackages.ARCHIVE_USERNAME+"/"+message,"","","",false));}
    }
    public View content(){return content(false);}
    public View content(boolean compact){Context context=host.getParentActivity();int thumbnail=compact?40:56;LinearLayout body=DevGramStudioControls.column(context);TextView hint=DevGramStudioControls.text(context,"Здесь можно сохранить изображения и шрифты работы отдельно. Баннер и видео открываются в архиве Telegram, где доступны их оригиналы.",compact?12:13,false,resources);hint.setPadding(AndroidUtilities.dp(compact?8:22),AndroidUtilities.dp(12),AndroidUtilities.dp(compact?8:22),AndroidUtilities.dp(18));body.addView(hint);
        for(Source source:sources){LinearLayout line=new LinearLayout(context);line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(AndroidUtilities.dp(compact?8:18),AndroidUtilities.dp(8),AndroidUtilities.dp(compact?8:16),AndroidUtilities.dp(8));if(source.download&&source.mime.startsWith("image/")){BackupImageView image=new BackupImageView(context);image.setRoundRadius(AndroidUtilities.dp(10));image.setImage(source.url,"100_100",null);line.addView(image,new LinearLayout.LayoutParams(AndroidUtilities.dp(thumbnail),AndroidUtilities.dp(thumbnail)));}else{ImageView icon=new ImageView(context);icon.setImageResource(source.download?R.drawable.msg_theme:R.drawable.msg_video);icon.setScaleType(ImageView.ScaleType.CENTER);icon.setColorFilter(Theme.getColor(Theme.key_windowBackgroundWhiteBlueText,resources));line.addView(icon,new LinearLayout.LayoutParams(AndroidUtilities.dp(thumbnail),AndroidUtilities.dp(thumbnail)));}LinearLayout words=DevGramStudioControls.column(context);words.setPadding(AndroidUtilities.dp(compact?8:14),0,0,0);TextView title=DevGramStudioControls.text(context,source.label,compact?13:15,true,resources);words.addView(title);TextView caption=DevGramStudioControls.text(context,source.download?"Сохранить оригинал":source.url.startsWith("https://t.me/")?"Открыть в Telegram":"Открыть оригинал",compact?10:12,false,resources);caption.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText,resources));words.addView(caption);line.addView(words,new LinearLayout.LayoutParams(0,-2,1));ImageView download=new ImageView(context);download.setImageResource(source.download?R.drawable.msg_download:R.drawable.msg_openin);download.setColorFilter(Theme.getColor(Theme.key_windowBackgroundWhiteBlueText,resources));line.addView(download,new LinearLayout.LayoutParams(AndroidUtilities.dp(compact?20:24),AndroidUtilities.dp(compact?20:24)));line.setBackground(Theme.createSelectorDrawable(Theme.getColor(Theme.key_listSelector,resources),2));line.setOnClickListener(v->{if(!valid()||busy)return;if(source.download){if(!DevGramAppearanceAccess.check(host,"profile.export",v))return;selected=source;destination(SINGLE,source.mime,source.filename);}else org.telegram.messenger.browser.Browser.openUrl(host.getParentActivity(),source.url);});body.addView(line);}
        if(sources.isEmpty()){TextView empty=DevGramStudioControls.text(context,"В работе нет исходных медиа.",14,false,resources);empty.setPadding(24,24,24,24);body.addView(empty);}
        TextSettingsCell pack=new TextSettingsCell(context,resources);pack.setText(DevGramAppearanceAccess.label(host,"profile.export",t("Сохранить пакет исходников")),false);pack.setOnClickListener(v->{if(!busy&&valid()&&DevGramAppearanceAccess.check(host,"profile.export",v))destination(PACKAGE,"application/zip","DevGram-work-"+work.optLong("id")+"-sources.zip");});body.addView(pack);status=DevGramStudioControls.text(context,"",13,false,resources);status.setPadding(AndroidUtilities.dp(22),AndroidUtilities.dp(10),AndroidUtilities.dp(22),AndroidUtilities.dp(18));body.addView(status);return body;
    }
    public void show(){if(!valid()||host.getParentActivity()==null)return;Context context=host.getParentActivity();ScrollView scroll=new ScrollView(context);scroll.addView(content());BottomSheet sheet=new BottomSheet.Builder(context,false,resources).setTitle(t("Исходные медиа")).setCustomView(scroll).create();sheet.fixNavigationBarKey(Theme.key_dialogBackground);host.showDialog(sheet);
    }
    private void destination(int request,String mime,String name){try{host.getParentActivity().startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(mime).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,name),request);}catch(Exception e){message(false);}}
    private void progress(int completed,int total){AndroidUtilities.runOnUIThread(()->{if(valid()&&status!=null)status.setText(t("Загружаю…")+" "+completed+"/"+total);});}
    private File fetch(Source source,File folder)throws Exception{
        if(!valid()||!DevGramProfilePolicy.allowed(viewer,"profile.export"))throw new IOException("canceled");String expected="https://api.devgram.space/badges/studio/";if(!source.url.startsWith(expected+"textures/")&&!source.url.startsWith(expected+"fonts/"))throw new IOException("origin");File target=new File(folder,source.filename);HttpURLConnection connection=(HttpURLConnection)new URL(source.url).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(12000);connection.setReadTimeout(20000);MessageDigest digest=MessageDigest.getInstance("SHA-256");try{if(connection.getResponseCode()!=200||connection.getContentLengthLong()>MAX_ASSET)throw new IOException("source");int total=0;byte[] buffer=new byte[16384];try(InputStream stream=connection.getInputStream();OutputStream output=new FileOutputStream(target)){int count;while((count=stream.read(buffer))!=-1){if(!valid()||!DevGramProfilePolicy.allowed(viewer,"profile.export")||(total+=count)>MAX_ASSET)throw new IOException("source");digest.update(buffer,0,count);output.write(buffer,0,count);}}StringBuilder sha=new StringBuilder();for(byte value:digest.digest())sha.append(String.format(Locale.ROOT,"%02x",value&255));if(!source.sha.equals(sha.toString()))throw new IOException("checksum");return target;}finally{connection.disconnect();}
    }
    public void result(int request,int result,Intent data){if(request!=SINGLE&&request!=PACKAGE)return;if(result!=Activity.RESULT_OK||data==null||data.getData()==null||!valid()||busy){selected=null;return;}Source one=selected;selected=null;if(request==SINGLE&&one==null)return;busy=true;progress(0,sources.size());android.net.Uri uri=data.getData();Utilities.globalQueue.postRunnable(()->{File folder=new File(ApplicationLoader.applicationContext.getCacheDir(),"devgram-work-sources/"+UUID.randomUUID());boolean success=false;try{if(!folder.mkdirs())throw new IOException("storage");File output;if(request==SINGLE)output=fetch(one,folder);else{output=new File(folder,"sources.zip");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(output))){JSONObject manifest=new JSONObject().put("format","devgram-work-sources-1").put("work",work.optLong("id")).put("version",work.optInt("version",1));JSONArray refs=new JSONArray();for(Source source:sources)refs.put(new JSONObject().put("name",source.label).put("file",source.download?"assets/"+source.filename:JSONObject.NULL).put("sha256",source.sha).put("url",source.url));manifest.put("sources",refs);entry(zip,"manifest.json",manifest.toString(2).getBytes(StandardCharsets.UTF_8));JSONObject design=new JSONObject().put("format","devgram-profile-1").put("document",document).put("theme",work.optJSONObject("theme"));entry(zip,"profile.json",design.toString(2).getBytes(StandardCharsets.UTF_8));int total=0,completed=0;for(Source source:sources){if(!source.download)continue;File file=fetch(source,folder);total+=file.length();if(total>MAX_PACKAGE)throw new IOException("size");zip.putNextEntry(new ZipEntry("assets/"+source.filename));try(InputStream stream=new FileInputStream(file)){copy(stream,zip);}zip.closeEntry();file.delete();progress(++completed,sources.size());}}}if(!valid()||!DevGramProfilePolicy.allowed(viewer,"profile.export"))throw new IOException("canceled");try(InputStream input=new FileInputStream(output);OutputStream stream=ApplicationLoader.applicationContext.getContentResolver().openOutputStream(uri)){if(stream==null)throw new IOException("destination");copy(input,stream);}success=true;}catch(Exception ignored){}finally{File[] files=folder.listFiles();if(files!=null)for(File file:files)file.delete();folder.delete();}boolean saved=success;AndroidUtilities.runOnUIThread(()->{busy=false;message(saved);});});}
    private void copy(InputStream input,OutputStream output)throws IOException{byte[] buffer=new byte[16384];int count;while((count=input.read(buffer))!=-1){if(!valid()||!DevGramProfilePolicy.allowed(viewer,"profile.export"))throw new IOException("canceled");output.write(buffer,0,count);}}
    private void entry(ZipOutputStream zip,String name,byte[] bytes)throws IOException{zip.putNextEntry(new ZipEntry(name));zip.write(bytes);zip.closeEntry();}
    private void message(boolean saved){if(valid()&&host.getParentActivity()!=null){String text=t(saved?"Файл сохранён":"Не удалось сохранить исходники");if(status!=null)status.setText(text);Toast.makeText(host.getParentActivity(),text,Toast.LENGTH_SHORT).show();}}
    public void close(){closed=true;selected=null;status=null;}
}
